private static string BuildMemoryOverviewBlockSourceText(CompressedMemoryBlock block)
{
	if (block == null)
	{
		return "";
	}
	string date = string.IsNullOrWhiteSpace(block.GameDate) ? ("第" + block.GameDayIndex + "日") : block.GameDate.Trim();
	string title = StripMemoryTitleDateTime(block.RichTitle);
	if (string.IsNullOrWhiteSpace(title))
	{
		title = "往日对话记忆";
	}
	string scenes = block.Scenes != null && block.Scenes.Count > 0 ? string.Join(" / ", block.Scenes.Select((string x) => (x ?? "").Trim()).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase)) : "地点未知";
	StringBuilder stringBuilder = new StringBuilder();
	stringBuilder.AppendLine("- 记忆块ID：" + ((block.Id ?? BuildCompressedMemoryBlockId(block.HeroId, block.GameDayIndex)).Trim()));
	stringBuilder.AppendLine("  日期时间地点：" + date + " " + FormatMemoryHourRange(block.StartHour, block.EndHour) + "｜" + scenes);
	stringBuilder.AppendLine("  标题：" + title);
	stringBuilder.AppendLine("  内容：" + (block.Summary ?? "").Trim());
	if (block.AfefLines != null && block.AfefLines.Count > 0)
	{
		stringBuilder.AppendLine("  AFEF事实参考：");
		foreach (string line in block.AfefLines)
		{
			if (!string.IsNullOrWhiteSpace(line))
			{
				stringBuilder.AppendLine("  " + line.Trim());
			}
		}
	}
	return stringBuilder.ToString().TrimEnd();
}

private static bool TryParseMemoryOverviewResponse(string content, Hero hero, MemoryOverviewJob job, MemoryOverviewState existingState, List<CompressedMemoryBlock> sourceBlocks, out MemoryOverviewState state, out string error)
{
	state = null;
	error = "";
	try
	{
		if (!TryParseBestSummaryJsonObject(content, new string[4] { "summary_content", "summaryContent", "summary", "content" }, null, out var jObject, out error))
		{
			return false;
		}
		if (!MemorySummaryRules.TryReadSummary(jObject, out string summary, out error))
		{
			return false;
		}
		string heroId = NormalizeMemoryHeroId(job?.HeroId ?? hero?.StringId);
		List<string> includedBlockIds = new List<string>();
		if (existingState != null && existingState.IncludedBlockIds != null)
		{
			includedBlockIds.AddRange(existingState.IncludedBlockIds);
		}
		foreach (CompressedMemoryBlock block in sourceBlocks ?? new List<CompressedMemoryBlock>())
		{
			if (block == null)
			{
				continue;
			}
			string blockId = (block.Id ?? BuildCompressedMemoryBlockId(block.HeroId, block.GameDayIndex)).Trim();
			if (!string.IsNullOrWhiteSpace(blockId))
			{
				includedBlockIds.Add(blockId);
			}
		}
		state = new MemoryOverviewState
		{
			HeroId = heroId,
			HeroName = hero?.Name?.ToString() ?? job?.HeroName ?? "NPC",
			Summary = summary,
			IncludedBlockIds = includedBlockIds.Distinct(StringComparer.OrdinalIgnoreCase).ToList(),
			UpdatedUtcTicks = DateTime.UtcNow.Ticks,
			LastError = ""
		};
		return true;
	}
	catch (Exception ex)
	{
		error = ex.Message;
		return false;
	}
}

