private void RunDailyMaintenanceSynchronously()
{
	TrySealPastDailyMemoryDrafts();
	QueueDirtyMemoryOverviewCandidatesForDeferredScan();
	ProcessMemoryOverviewCandidateScanBudget(0L, double.MaxValue);
	TryStartMemorySummaryQueue();
	TryDiscontinueLandlessModRebelKingdoms("daily_tick");
	EnsureWeekZeroOpeningSummaryEvents();
	TryRecordMissedStrategicWorldEvents();
	ApplyKingdomStabilityRelationAdjustments();
	int currentGameDayIndexSafe = GetCurrentGameDayIndexSafe();
	int weekIndex = (currentGameDayIndexSafe > 0) ? (currentGameDayIndexSafe / 7) : 0;
	if (currentGameDayIndexSafe > 0 && currentGameDayIndexSafe % 7 == 0)
	{
		TryProcessWeeklyKingdomRebellions(weekIndex);
	}
	if (_weeklyReportGenerationInProgress)
	{
		return;
	}
	DuelSettings settings = DuelSettings.GetSettings();
	int missingWeek = _weeklyAutoSchedule.SelectWeek(_lastAutoGeneratedWeeklyReportWeek,
		currentGameDayIndexSafe, weekIndex, _weeklyReportGenerationInProgress,
		settings != null && settings.IsLegacyWeeklyAutoGenerationActive(), AutomaticKingdomRebellions.FlowActive);
	if (missingWeek <= 0)
	{
		return;
	}
	StartAutoWeeklyReportsForWeek(missingWeek, currentGameDayIndexSafe);
}

private void EnqueueDailyMaintenanceForCurrentDay(string reason)
{
	int currentGameDayIndexSafe = GetCurrentGameDayIndexSafe();
	int weekIndex = (currentGameDayIndexSafe > 0) ? (currentGameDayIndexSafe / 7) : 0;
	if (currentGameDayIndexSafe > 0 && currentGameDayIndexSafe % 7 == 0)
	{
		EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.ProcessWeeklyKingdomRebellions, currentGameDayIndexSafe, weekIndex, reason: reason);
	}
	QueueDeferredAutoWeeklyReportsForWeek(weekIndex, currentGameDayIndexSafe, reason);
	EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.SealPastDailyMemoryDrafts, currentGameDayIndexSafe, reason: reason);
	EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.QueueDirtyMemoryOverviewScan, currentGameDayIndexSafe, reason: reason);
	EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.StartMemorySummaryQueue, currentGameDayIndexSafe, reason: reason);
	EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.DiscontinueLandlessRebelKingdoms, currentGameDayIndexSafe, reason: reason);
	EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.EnsureWeekZeroOpeningSummaryEvents, currentGameDayIndexSafe, reason: reason);
	EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.RecordMissedStrategicWorldEvents, currentGameDayIndexSafe, reason: reason);
	EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.ApplyKingdomStabilityRelationAdjustments, currentGameDayIndexSafe, reason: reason);
}

private void QueueDeferredAutoWeeklyReportsForWeek(int weekIndex, int currentGameDayIndexSafe, string reason)
{
	DuelSettings settings = DuelSettings.GetSettings();
	int missingWeek = _weeklyAutoSchedule.SelectWeek(_lastAutoGeneratedWeeklyReportWeek,
		currentGameDayIndexSafe, weekIndex, _weeklyReportGenerationInProgress,
		settings != null && settings.IsLegacyWeeklyAutoGenerationActive(), AutomaticKingdomRebellions.FlowActive);
	if (missingWeek <= 0)
	{
		return;
	}
	int startDay = WeeklyReportSchedulePolicy.GetStartDay(missingWeek);
	int endDay = WeeklyReportSchedulePolicy.GetEndDay(missingWeek);
	EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind.PrepareAutoWeeklyReports, endDay, missingWeek, startDay, endDay, reason);
}

private void EnqueueDailyMaintenanceJob(DailyMaintenanceTaskKind kind, int dayIndex = -1, int weekIndex = 0, int startDay = 0, int endDay = 0, string reason = "")
{
	string key = BuildDailyMaintenanceJobKey(kind, dayIndex, weekIndex, startDay, endDay);
	if (!_dailyMaintenanceJobKeys.Add(key))
	{
		return;
	}
	_dailyMaintenanceQueue.Enqueue(new DailyMaintenanceJob
	{
		Kind = kind,
		DayIndex = dayIndex,
		WeekIndex = weekIndex,
		StartDay = startDay,
		EndDay = endDay,
		Reason = (reason ?? "").Trim()
	});
}

private static string BuildDailyMaintenanceJobKey(DailyMaintenanceTaskKind kind, int dayIndex, int weekIndex, int startDay, int endDay)
{
	return kind + ":" + dayIndex + ":" + weekIndex + ":" + startDay + ":" + endDay;
}


private bool HasPendingDeferredDailyMaintenanceWork()
{
	return _dailyMaintenanceQueue.Count > 0 || _pendingMemoryOverviewCandidateScanIds.Count > 0 || _pendingAutoWeeklyReportBuild != null;
}

private void ProcessDeferredDailyMaintenance()
{
	if (!IsDeferredDailyMaintenanceEnabled() || !HasPendingDeferredDailyMaintenanceWork())
	{
		return;
	}
	ResolveDailyMaintenanceBudget(out long startTimestamp, out double budgetMs);
	if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs)) return;
	if (_pendingAutoWeeklyReportBuild != null && !AutomaticKingdomRebellions.FlowActive)
	{
		using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessPendingAutoWeeklyReportBuild"))
		{
			ProcessPendingAutoWeeklyReportBuildBudget(startTimestamp, budgetMs);
		}
		if (_pendingAutoWeeklyReportBuild != null || IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			return;
		}
	}
	int processedScanCount;
	using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessMemoryOverviewCandidateScan"))
	{
		processedScanCount = ProcessMemoryOverviewCandidateScanBudget(startTimestamp, budgetMs);
	}
	int processedJobCount = 0;
	while (_dailyMaintenanceQueue.Count > 0 && processedJobCount < DailyMaintenanceMaxJobsPerTick && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
	{
		DailyMaintenanceJob job = _dailyMaintenanceQueue.Dequeue();
		_dailyMaintenanceJobKeys.Remove(BuildDailyMaintenanceJobKey(job.Kind, job.DayIndex, job.WeekIndex, job.StartDay, job.EndDay));
		bool completed;
		using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.Job." + job.Kind))
		{
			completed = ExecuteDailyMaintenanceJob(job, startTimestamp, budgetMs);
		}
		if (!completed)
		{
			EnqueueDailyMaintenanceJob(job.Kind, job.DayIndex, job.WeekIndex, job.StartDay, job.EndDay, job.Reason);
		}
		processedJobCount++;
		using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessMemoryOverviewCandidateScan"))
		{
			processedScanCount += ProcessMemoryOverviewCandidateScanBudget(startTimestamp, budgetMs);
		}
	}
	if (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
	{
		using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessPendingAutoWeeklyReportBuild"))
		{
			ProcessPendingAutoWeeklyReportBuildBudget(startTimestamp, budgetMs);
		}
	}
	using (PerfProbe.Scope("MyBehavior.DeferredDailyMaintenance.ProcessMemoryOverviewCandidateScan"))
	{
		processedScanCount += ProcessMemoryOverviewCandidateScanBudget(startTimestamp, budgetMs);
	}
	if (processedScanCount > 0 && !_memorySummaryRunOwner.IsRunning && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
	{
		TryStartMemorySummaryQueue();
	}
}

private bool ExecuteDailyMaintenanceJob(DailyMaintenanceJob job, long startTimestamp, double budgetMs)
{
	if (job == null)
	{
		return true;
	}
	try
	{
		if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			return false;
		}
		switch (job.Kind)
		{
		case DailyMaintenanceTaskKind.SealPastDailyMemoryDrafts:
			if (!TrySealPastDailyMemoryDrafts(startTimestamp, budgetMs))
			{
				return false;
			}
			break;
		case DailyMaintenanceTaskKind.StartMemorySummaryQueue:
			TryStartMemorySummaryQueue();
			break;
		case DailyMaintenanceTaskKind.QueueDirtyMemoryOverviewScan:
			QueueDirtyMemoryOverviewCandidatesForDeferredScan();
			break;
		case DailyMaintenanceTaskKind.QueueFullMemoryOverviewScan:
			QueueAllMemoryOverviewCandidatesForDeferredScan();
			break;
		case DailyMaintenanceTaskKind.DiscontinueLandlessRebelKingdoms:
			TryDiscontinueLandlessModRebelKingdoms(string.IsNullOrWhiteSpace(job.Reason) ? "deferred_daily_tick" : job.Reason);
			break;
		case DailyMaintenanceTaskKind.EnsureWeekZeroOpeningSummaryEvents:
			if (!ProcessWeekZeroOpeningSummaryEventsSlice())
			{
				return false;
			}
			break;
		case DailyMaintenanceTaskKind.RecordMissedStrategicWorldEvents:
			if (!ProcessMissedStrategicWorldEventsSlice())
			{
				return false;
			}
			break;
		case DailyMaintenanceTaskKind.ApplyKingdomStabilityRelationAdjustments:
			if (!ProcessKingdomStabilityRelationAdjustmentsSlice())
			{
				return false;
			}
			break;
		case DailyMaintenanceTaskKind.ProcessWeeklyKingdomRebellions:
			return ProcessWeeklyKingdomRebellionsSlice(job.WeekIndex);
		case DailyMaintenanceTaskKind.PrepareAutoWeeklyReports:
			TryInitializePendingAutoWeeklyReportBuild(job);
			break;
		}
		return true;
	}
	catch (Exception ex)
	{
		Logger.Log("DailyMaintenance", "[ERROR] " + job.Kind + " failed: " + ex.Message);
		return true;
	}
}

private bool ProcessKingdomStabilityRelationAdjustmentsSlice()
{
	if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
	{
		ClearKingdomStabilityRelationAdjustments();
		KingdomMaintenance.ResetRelations();
		return true;
	}
	List<Kingdom> kingdoms = Kingdom.All?.Where((Kingdom x) => x != null).ToList() ?? new List<Kingdom>();
	return KingdomMaintenance.AdvanceRelations(kingdoms.Count, index => ApplyKingdomStabilityRelationAdjustmentsForKingdom(kingdoms[index]));
}

private void TryInitializePendingAutoWeeklyReportBuild(DailyMaintenanceJob job)
{
	if (job == null || job.WeekIndex <= 0 || _lastAutoGeneratedWeeklyReportWeek >= job.WeekIndex)
	{
		return;
	}
	if (_weeklyReportGenerationInProgress || _pendingAutoWeeklyReportBuild != null)
	{
		if (_pendingAutoWeeklyReportBuild == null || _pendingAutoWeeklyReportBuild.WeekIndex != job.WeekIndex)
		{
			_weeklyAutoSchedule.Defer(job.WeekIndex);
		}
		return;
	}
	if (AutomaticKingdomRebellions.FlowActive)
	{
		_weeklyAutoSchedule.Defer(job.WeekIndex);
		return;
	}
	DuelSettings settings = DuelSettings.GetSettings();
	if (settings == null || !settings.IsLegacyWeeklyAutoGenerationActive())
	{
		return;
	}
	_pendingAutoWeeklyReportBuild = new PendingAutoWeeklyReportBuild
	{
		SourceSnapshot = _weeklyReportMaterialRevisions.Capture(Math.Max(0, job.StartDay), Math.Max(job.StartDay, job.EndDay)),
		WeekIndex = job.WeekIndex,
		StartDay = Math.Max(0, job.StartDay),
		EndDay = Math.Max(job.StartDay, job.EndDay),
		Kingdoms = GetDevEditableKingdoms().Where(IsKingdomEligibleForWeeklyReport).ToList(),
		EventSourceMaterialSnapshot = SanitizeEventSourceMaterials(_eventSourceMaterials)
	};
	_weeklyReportGenerationInProgress = true;
	_weeklyAutoSchedule.Clear();
}

private void ProcessPendingAutoWeeklyReportBuildBudget(long startTimestamp, double budgetMs)
{
	PendingAutoWeeklyReportBuild context = _pendingAutoWeeklyReportBuild;
	if (context == null || AutomaticKingdomRebellions.FlowActive)
	{
		return;
	}
	try
	{
		if (!context.PreviewGroupsComplete && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			using (PerfProbe.Scope("MyBehavior.AutoWeeklyReport.BuildPreviewGroupsSlice"))
			{
				context.PreviewGroupsComplete = ProcessPendingAutoWeeklyReportPreviewGroupsBudget(context, startTimestamp, budgetMs);
			}
		}
		if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.PreviewGroupsComplete)
		{
			return;
		}
		ProcessPendingWeeklyReportAggregationBudget(context, startTimestamp, budgetMs);
		if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || context.AggregationCursor?.Complete != true)
		{
			return;
		}
		ProcessPendingWeeklyReportPromptMaterialsBudget(context, startTimestamp, budgetMs);
		if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || context.PromptMaterialCursor?.Complete != true)
		{
			return;
		}
		if (!context.Ordered && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			context.Groups = OrderWeeklyReportGenerationGroups((context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).ToList());
			context.Ordered = true;
		}
		if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.Ordered)
		{
			return;
		}
		ProcessPendingWeeklyReportBatchPromptsBudget(context, startTimestamp, budgetMs);
		if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || context.BatchPromptCursor?.Complete != true)
		{
			return;
		}
		if (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			FinalizePendingAutoWeeklyReportBuild(context);
		}
	}
	catch (Exception ex)
	{
		_pendingAutoWeeklyReportBuild = null;
		_weeklyReportGenerationInProgress = false;
		Logger.Log("EventWeeklyReport", "[ERROR] deferred auto weekly report build failed: " + ex);
	}
}

private bool ProcessPendingAutoWeeklyReportPreviewGroupsBudget(PendingAutoWeeklyReportBuild context, long startTimestamp, double budgetMs)
{
	if (context == null)
	{
		return true;
	}
	if (!context.PreviewGroupsInitialized)
	{
		context.Groups = new List<WeeklyEventMaterialPreviewGroup>
		{
			CreateWorldWeeklyEventMaterialPreviewGroup()
		};
		foreach (Kingdom kingdom in context.Kingdoms ?? new List<Kingdom>())
		{
			context.Groups.Add(CreateKingdomWeeklyEventMaterialPreviewGroup(kingdom));
		}
		context.RecentActionCursor = new WeeklyActionMaterialCursor<NpcActionEntry, Hero>((_npcRecentActions ?? new Dictionary<string, List<NpcActionEntry>>()).ToList());
		context.MajorActionCursor = new WeeklyActionMaterialCursor<NpcActionEntry, Hero>((_npcMajorActions ?? new Dictionary<string, List<NpcActionEntry>>()).ToList());
		context.PreviewGroupsInitialized = true;
		return false;
	}
	while (context.PreviewSourceMaterialIndex < (context.EventSourceMaterialSnapshot?.Count ?? 0) && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
	{
		EventSourceMaterialEntry item = context.EventSourceMaterialSnapshot[context.PreviewSourceMaterialIndex++];
		ProcessPendingAutoWeeklyReportSourceMaterial(context, item);
	}
	if (context.PreviewSourceMaterialIndex < (context.EventSourceMaterialSnapshot?.Count ?? 0))
	{
		return false;
	}
	while (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) && !ProcessPendingAutoWeeklyReportActionSlice(context, recentOnly: true))
	{
	}
	if (context.RecentActionCursor != null && !context.RecentActionCursor.Complete)
	{
		return false;
	}
	while (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) && !ProcessPendingAutoWeeklyReportActionSlice(context, recentOnly: false))
	{
	}
	return context.MajorActionCursor == null || context.MajorActionCursor.Complete;
}

private void ProcessPendingAutoWeeklyReportSourceMaterial(PendingAutoWeeklyReportBuild context, EventSourceMaterialEntry item)
{
	if (context == null || item == null || item.Day < context.StartDay || item.Day > context.EndDay || context.Groups == null || context.Groups.Count == 0)
	{
		return;
	}
	if (item.IncludeInWorld)
	{
		TryAddPreviewSourceMaterial(context.Groups[0].Materials, item);
	}
	for (int i = 0; i < context.Kingdoms.Count && i + 1 < context.Groups.Count; i++)
	{
		Kingdom kingdom = context.Kingdoms[i];
		if (item.IncludeInKingdom && IsKingdomEligibleForWeeklyReport(kingdom) && DoesEventSourceMaterialRelateToKingdom(item, kingdom))
		{
			TryAddPreviewSourceMaterial(context.Groups[i + 1].Materials, item);
		}
	}
}

private bool ProcessPendingAutoWeeklyReportActionSlice(PendingAutoWeeklyReportBuild context, bool recentOnly)
{
	if (context == null)
	{
		return true;
	}
	WeeklyActionMaterialCursor<NpcActionEntry, Hero> cursor = recentOnly ? context.RecentActionCursor : context.MajorActionCursor;
	return cursor == null || cursor.Advance(FindHeroById,
		(hero, action) => ProcessPendingAutoWeeklyReportNpcAction(context, hero, action, recentOnly));
}

private void ProcessPendingAutoWeeklyReportNpcAction(PendingAutoWeeklyReportBuild context, Hero hero, NpcActionEntry action, bool recentOnly)
{
	if (context == null || hero == null || action == null || action.Day < context.StartDay || action.Day > context.EndDay || context.Groups == null || context.Groups.Count == 0)
	{
		return;
	}
	if (ShouldIncludeWorldPreviewAction(hero, action))
	{
		TryAddPreviewActionMaterial(context.Groups[0].Materials, hero, action, recentOnly);
	}
	for (int i = 0; i < context.Kingdoms.Count && i + 1 < context.Groups.Count; i++)
	{
		Kingdom kingdom = context.Kingdoms[i];
		if (!IsKingdomEligibleForWeeklyReport(kingdom) || !DoesNpcActionRelateToKingdom(action, kingdom))
