		{
			text5 = text4;
		}
		string text6 = (tournamentHero2 != null ? "hero:" : "troop:") + text5;
		if (!dictionary.ContainsKey(text6))
		{
			dictionary[text6] = list.Count;
			list.Add(text4 + BuildTournamentCharacterRoleSuffix(winner));
