	private void ApplyRulingClanSettlementLoyaltyAdjustmentForLowClanCountKingdom(Town town)
	{
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			return;
		}
		if (town?.Settlement == null || !town.Settlement.IsFortification)
