private static HashSet<uint> CollectUsedFactionPrimaryColors(Kingdom oldKingdom, Clan founderClan)
{
	HashSet<uint> hashSet = new HashSet<uint>();
	try
	{
		foreach (Kingdom item in Kingdom.All)
		{
			if (item != null && !item.IsEliminated)
			{
