	private void QueueAutomaticKingdomRebellion(KingdomRebellionResolutionResult result, string civilWarFactionId = null)
{
	if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
	{
		return;
	}
	if (result?.Kingdom == null || result.SelectedClan == null)
	{
		return;
	}
	if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(result.Kingdom))
	{
		Logger.Log("KingdomRebellion", "[SKIP] player kingdom stability rebellion immunity blocked automatic queue. kingdom=" + GetKingdomId(result.Kingdom) + " clan=" + GetClanId(result.SelectedClan));
		return;
	}
	KingdomRebellionCandidateInfo kingdomRebellionCandidateInfo = result.Candidates?.FirstOrDefault((KingdomRebellionCandidateInfo x) => x != null && x.Clan == result.SelectedClan);
	PendingAutomaticKingdomRebellionContext item = new PendingAutomaticKingdomRebellionContext
	{
		KingdomId = GetKingdomId(result.Kingdom),
		ClanId = GetClanId(result.SelectedClan),
		WeekIndex = result.WeekIndex,
		StabilityValue = result.StabilityValue,
		StabilityTierText = result.StabilityTierText,
		RelationToKing = kingdomRebellionCandidateInfo?.RelationToKing ?? 0,
		TownCount = kingdomRebellionCandidateInfo?.TownCount ?? 0,
		CastleCount = kingdomRebellionCandidateInfo?.CastleCount ?? 0,
		FollowerClanIds = (result.SelectedFollowerClans ?? new List<Clan>()).Where((Clan x) => x != null && x != result.SelectedClan).Select(GetClanId).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList()
		,
		CivilWarFactionId = civilWarFactionId ?? ""
	};
	AutomaticKingdomRebellions.Enqueue(item);
}

private void CancelPendingAutomaticKingdomRebellions(string reason)
{
	AutomaticKingdomRebellions.Cancel();
	Logger.Log("KingdomRebellion", "[CANCEL] Pending automatic rebellions cleared. reason=" + (reason ?? ""));
}

private void TryStartNextAutomaticKingdomRebellionAsync()
{
	if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
	{
		CancelPendingAutomaticKingdomRebellions("disabled_before_start");
		TryStartDeferredAutoWeeklyReports();
		return;
	}
	if (!AutomaticKingdomRebellions.TryDequeue(out PendingAutomaticKingdomRebellionContext pendingAutomaticKingdomRebellionContext))
	{
		return;
	}
	Kingdom kingdom = FindKingdomById(pendingAutomaticKingdomRebellionContext.KingdomId);
	Clan clan = FindClanById(pendingAutomaticKingdomRebellionContext.ClanId);
	List<Clan> list = (pendingAutomaticKingdomRebellionContext.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan).ToList();
	if (IsStaleCivilWarRebellion(pendingAutomaticKingdomRebellionContext))
	{
		ContinueAutomaticKingdomRebellionFlow();
		return;
	}
	if (kingdom == null || clan == null)
	{
		NotifyCivilWarRebellionFailed(pendingAutomaticKingdomRebellionContext, "目标王国或家族状态已变化");
		ShowAutomaticKingdomRebellionCompletionPopup(pendingAutomaticKingdomRebellionContext, kingdom, clan, list, success: false, "本周自动叛乱已命中，但目标王国或家族状态已变化，无法继续执行。");
		return;
	}
	if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
	{
		Logger.Log("KingdomRebellion", "[SKIP] player kingdom stability rebellion immunity blocked queued automatic rebellion before naming. kingdom=" + GetKingdomId(kingdom) + " clan=" + GetClanId(clan));
		NotifyCivilWarRebellionFailed(pendingAutomaticKingdomRebellionContext, "玩家王国稳定度叛乱免疫");
		ContinueAutomaticKingdomRebellionFlow();
		return;
	}
	string[] rebellionExistingNames = CaptureRebellionExistingNames();
	BuildRebelKingdomNamingRequest(clan, kingdom, pendingAutomaticKingdomRebellionContext.WeekIndex, list, out var systemPrompt, out var userPrompt, rebellionExistingNames);
	long namingRequestVersion = AutomaticKingdomRebellions.BeginNaming();
	InformationManager.ShowInquiry(new InquiryData("正在生成叛乱建国命名", "系统正在为本周自动叛乱生成新王国的名称与百科简介。\n\n这一步完成前不会继续本轮自动叛乱与周报流程。\n请稍候，结果完成后会自动弹出。", isAffirmativeOptionShown: false, isNegativeOptionShown: false, "", "", null, null), pauseGameActiveState: true);
	long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
	string logTarget = "自动叛乱建国命名 - " + GetClanId(clan);
	Task.Run(delegate
	{
		RebelKingdomNamingResult namingResult;
		try
		{
			namingResult = GenerateRebelKingdomNamingFromPrompts(systemPrompt, userPrompt, logTarget, RebelKingdomNamingMaxAttempts, rebellionExistingNames);
		}
		catch (Exception ex)
		{
			namingResult = BuildFailedRebelKingdomNamingResult("叛乱建国命名后台任务异常：" + ex.Message);
		}
		EnqueueKingdomRebellionNamingMainThreadAction(runtimeGeneration, delegate
		{
			if (AutomaticKingdomRebellions.CompleteNaming(namingRequestVersion, pendingAutomaticKingdomRebellionContext))
				pendingAutomaticKingdomRebellionContext.NamingResult = namingResult;
		}, "automatic_rebellion_naming");
	});
}

private void ProcessPendingAutomaticKingdomRebellionResult()
{
	if (!AutomaticKingdomRebellions.TryTakeReady(out PendingAutomaticKingdomRebellionContext pendingAutomaticKingdomRebellionContext))
	{
		return;
	}
	if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
	{
		CancelPendingAutomaticKingdomRebellions("disabled_before_execute");
		TryStartDeferredAutoWeeklyReports();
		return;
	}
	if (pendingAutomaticKingdomRebellionContext == null)
	{
		return;
	}
	Kingdom kingdom = FindKingdomById(pendingAutomaticKingdomRebellionContext.KingdomId);
	Clan clan = FindClanById(pendingAutomaticKingdomRebellionContext.ClanId);
	List<Clan> list = (pendingAutomaticKingdomRebellionContext.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan).ToList();
	string executionMessage;
	bool success;
	// The civil-war faction may have timed out or dissolved while the name was being generated.
	if (IsStaleCivilWarRebellion(pendingAutomaticKingdomRebellionContext))
	{
		InformationManager.HideInquiry();
		ContinueAutomaticKingdomRebellionFlow();
		return;
	}
	if (kingdom == null || clan == null)
	{
		success = false;
		executionMessage = "叛乱命名已完成，但目标王国或家族状态已变化，无法继续执行。";
	}
	else if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
	{
		success = false;
		executionMessage = GetKingdomDisplayName(kingdom, "该王国") + " 当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，本次自动稳定度叛乱已跳过。";
	}
	else
	{
		if (!IsRebelKingdomNamingSuccess(pendingAutomaticKingdomRebellionContext.NamingResult))
		{
			ShowAutomaticKingdomRebellionNamingFailurePopup(pendingAutomaticKingdomRebellionContext, kingdom, clan, list, afterApiRepair: false);
			return;
		}
		success = TryExecuteKingdomRebellionWithNaming(clan, kingdom, pendingAutomaticKingdomRebellionContext.WeekIndex, forceTrigger: false, pendingAutomaticKingdomRebellionContext.RelationToKing, pendingAutomaticKingdomRebellionContext.TownCount, pendingAutomaticKingdomRebellionContext.CastleCount, pendingAutomaticKingdomRebellionContext.NamingResult, list, out executionMessage);
		if (success && !string.IsNullOrWhiteSpace(pendingAutomaticKingdomRebellionContext.CivilWarFactionId))
		{
			TeamModuleServices.CivilWar.NotifyRebelKingdomCreated(pendingAutomaticKingdomRebellionContext.CivilWarFactionId, clan?.Kingdom, pendingAutomaticKingdomRebellionContext.WeekIndex);
		}
	}
	if (!success) NotifyCivilWarRebellionFailed(pendingAutomaticKingdomRebellionContext, executionMessage);
	ShowAutomaticKingdomRebellionCompletionPopup(pendingAutomaticKingdomRebellionContext, kingdom, clan, list, success, executionMessage);
}

// Civil-war requests: the owner may have dissolved the faction while this entry waited in the queue.
private static bool IsStaleCivilWarRebellion(PendingAutomaticKingdomRebellionContext context)
{
	string factionId = context?.CivilWarFactionId;
	if (string.IsNullOrWhiteSpace(factionId) || TeamModuleServices.CivilWar.IsRebellionRequestActive(factionId)) return false;
	Logger.Log("KingdomCivilWar", "[SKIP] stale civil war rebellion request faction=" + factionId);
	return true;
}

private static void NotifyCivilWarRebellionFailed(PendingAutomaticKingdomRebellionContext context, string reason)
{
	if (!string.IsNullOrWhiteSpace(context?.CivilWarFactionId)) TeamModuleServices.CivilWar.NotifyRebellionFailed(context.CivilWarFactionId, reason);
}

private void ShowAutomaticKingdomRebellionCompletionPopup(PendingAutomaticKingdomRebellionContext context, Kingdom kingdom, Clan clan, List<Clan> followerClans, bool success, string executionMessage)
{
	StringBuilder stringBuilder = new StringBuilder();
	if (kingdom != null)
	{
		stringBuilder.AppendLine("王国：" + GetKingdomDisplayName(kingdom, "某王国"));
	}
	if (!string.IsNullOrWhiteSpace(context?.StabilityTierText))
	{
		stringBuilder.AppendLine("触发时稳定度：" + context.StabilityValue + "（" + context.StabilityTierText + "）");
	}
	if (clan != null)
	{
		stringBuilder.AppendLine("主导家族：" + GetClanDisplayName(clan));
	}
	if (context?.NamingResult != null)
	{
		if (!success)
		{
			ReportRebelKingdomNamingFailure(context.NamingResult);
		}
		stringBuilder.AppendLine();
		AppendRebelKingdomNamingResultLines(stringBuilder, context.NamingResult);
	}
	if (followerClans != null && followerClans.Count > 0)
	{
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("联合响应家族：");
		stringBuilder.AppendLine("- " + string.Join("、", followerClans.Select(GetClanDisplayName)));
	}
	stringBuilder.AppendLine();
	stringBuilder.AppendLine("执行结果：");
	stringBuilder.AppendLine((executionMessage ?? "").Trim());
	if (AutomaticKingdomRebellions.PendingCount > 0)
	{
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("后续仍有 " + AutomaticKingdomRebellions.PendingCount + " 场自动叛乱待处理。点击“继续”后将进入下一场。");
	}
	InformationManager.HideInquiry();
	InformationManager.ShowInquiry(new InquiryData(success ? "自动叛乱执行完成" : "自动叛乱执行失败", stringBuilder.ToString().TrimEnd(), isAffirmativeOptionShown: true, isNegativeOptionShown: false, "继续", "", delegate
	{
		ContinueAutomaticKingdomRebellionFlow();
	}, null), pauseGameActiveState: true);
}

private void ShowAutomaticKingdomRebellionNamingFailurePopup(PendingAutomaticKingdomRebellionContext context, Kingdom kingdom, Clan clan, List<Clan> followerClans, bool afterApiRepair)
{
	StringBuilder stringBuilder = new StringBuilder();
	stringBuilder.AppendLine("本周自动叛乱已命中，但叛乱建国命名没有成功。系统不会使用本地国名继续建国。");
	stringBuilder.AppendLine();
	if (kingdom != null)
	{
		stringBuilder.AppendLine("王国：" + GetKingdomDisplayName(kingdom, "某王国"));
	}
	if (clan != null)
	{
		stringBuilder.AppendLine("主导家族：" + GetClanDisplayName(clan));
	}
	if (followerClans != null && followerClans.Count > 0)
	{
		stringBuilder.AppendLine("联合响应家族：" + string.Join("、", followerClans.Select(GetClanDisplayName)));
	}
	stringBuilder.AppendLine();
	ReportRebelKingdomNamingFailure(context?.NamingResult);
	AppendRebelKingdomNamingResultLines(stringBuilder, context?.NamingResult);
	stringBuilder.AppendLine();
	stringBuilder.AppendLine(afterApiRepair ? "API 配置流程已返回。请重新生成叛乱建国命名，或跳过本次自动叛乱。" : "请先重新填写事件/叛乱API信息。修正后可回到这里重新生成命名。");
	InformationManager.HideInquiry();
	InformationManager.ShowInquiry(new InquiryData(afterApiRepair ? "重试叛乱建国命名" : "叛乱建国命名失败", stringBuilder.ToString().TrimEnd(), isAffirmativeOptionShown: true, isNegativeOptionShown: true, afterApiRepair ? "重新生成命名" : "调整API信息", "跳过本次", delegate
	{
		if (afterApiRepair)
		{
			RetryAutomaticKingdomRebellionNamingAsync(context);
		}
		else
		{
			_blockedAutomaticKingdomRebellionContext = context;
			_blockedDevForcedKingdomRebellionContext = null;
			OpenKingdomRebellionApiRepairFlow();
		}
	}, delegate
	{
		if (ReferenceEquals(_blockedAutomaticKingdomRebellionContext, context))
		{
			_blockedAutomaticKingdomRebellionContext = null;
		}
		_kingdomRebellionReopenAfterApiConfig = false;
		NotifyCivilWarRebellionFailed(context, "跳过了叛乱建国命名");
		ContinueAutomaticKingdomRebellionFlow();
	}), pauseGameActiveState: true);
}

private void RetryAutomaticKingdomRebellionNamingAsync(PendingAutomaticKingdomRebellionContext context)
{
	_blockedAutomaticKingdomRebellionContext = null;
	_kingdomRebellionReopenAfterApiConfig = false;
	if (context == null)
	{
		ContinueAutomaticKingdomRebellionFlow();
		return;
	}
	if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
	{
		CancelPendingAutomaticKingdomRebellions("disabled_before_rebellion_naming_retry");
		TryStartDeferredAutoWeeklyReports();
		return;
	}
	if (!AutomaticKingdomRebellions.CanStart)
	{
		return;
	}
	Kingdom kingdom = FindKingdomById(context.KingdomId);
	Clan clan = FindClanById(context.ClanId);
	List<Clan> list = (context.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan).ToList();
	// The player may have spent weeks in the API repair flow; the civil-war faction may be gone by now.
	if (IsStaleCivilWarRebellion(context))
	{
		ContinueAutomaticKingdomRebellionFlow();
		return;
	}
	if (kingdom == null || clan == null)
	{
		NotifyCivilWarRebellionFailed(context, "目标王国或家族状态已变化");
		ShowAutomaticKingdomRebellionCompletionPopup(context, kingdom, clan, list, success: false, "叛乱命名重试前目标王国或家族状态已变化，无法继续执行。");
		return;
	}
	if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
	{
		NotifyCivilWarRebellionFailed(context, "玩家王国稳定度叛乱免疫");
		ShowAutomaticKingdomRebellionCompletionPopup(context, kingdom, clan, list, success: false, GetKingdomDisplayName(kingdom, "该王国") + " 当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，本次自动稳定度叛乱已跳过。");
		return;
	}
	string[] rebellionExistingNames = CaptureRebellionExistingNames();
	BuildRebelKingdomNamingRequest(clan, kingdom, context.WeekIndex, list, out var systemPrompt, out var userPrompt, rebellionExistingNames);
	long namingRequestVersion = AutomaticKingdomRebellions.BeginNaming();
	InformationManager.ShowInquiry(new InquiryData("正在重新生成叛乱建国命名", "系统正在按修正后的事件/叛乱API配置重新请求新王国名称与百科简介。\n\n这一步完成前不会继续本轮自动叛乱与周报流程。", isAffirmativeOptionShown: false, isNegativeOptionShown: false, "", "", null, null), pauseGameActiveState: true);
	long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
	string logTarget = "自动叛乱建国命名重试 - " + GetClanId(clan);
	Task.Run(delegate
	{
		RebelKingdomNamingResult namingResult;
		try
		{
			namingResult = GenerateRebelKingdomNamingFromPrompts(systemPrompt, userPrompt, logTarget, RebelKingdomNamingMaxAttempts, rebellionExistingNames);
		}
		catch (Exception ex)
		{
			namingResult = BuildFailedRebelKingdomNamingResult("叛乱建国命名重试后台任务异常：" + ex.Message);
		}
		EnqueueKingdomRebellionNamingMainThreadAction(runtimeGeneration, delegate
		{
			if (AutomaticKingdomRebellions.CompleteNaming(namingRequestVersion, context))
				context.NamingResult = namingResult;
		}, "automatic_rebellion_naming_retry");
	});
}

private void ContinueAutomaticKingdomRebellionFlow()
{
	if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
	{
		CancelPendingAutomaticKingdomRebellions("disabled_before_continue");
		TryStartDeferredAutoWeeklyReports();
		return;
	}
	if (AutomaticKingdomRebellions.PendingCount > 0)
	{
		TryStartNextAutomaticKingdomRebellionAsync();
		return;
	}
	AutomaticKingdomRebellions.FinishFlow();
	TryStartDeferredAutoWeeklyReports();
}

private static Settlement ResolveGatheringPointSettlement(IMapPoint gatheringPoint, MobileParty fallbackParty = null)
{
	if (gatheringPoint is Settlement settlement)
	{
		return settlement;
	}
	try
	{
		if (gatheringPoint != null)
		{
			Settlement settlement2 = Helpers.SettlementHelper.FindNearestSettlementToPoint(gatheringPoint.Position, (Settlement x) => x != null && !x.IsHideout);
			if (settlement2 != null)
			{
				return settlement2;
			}
		}
	}
	catch
	{
	}
	try
	{
		if (fallbackParty != null)
		{
			return Helpers.SettlementHelper.FindNearestSettlementToMobileParty(fallbackParty, MobileParty.NavigationType.All, (Settlement x) => x != null && !x.IsHideout);
		}
	}
	catch
	{
	}
	return null;
}

private static Settlement ResolveSettlementForPartyBase(PartyBase party)
{
	MobileParty mobileParty = party?.MobileParty;
	if (mobileParty == null)
	{
		return null;
	}
	return mobileParty.BesiegedSettlement ?? ResolveSiegeSettlement(mobileParty.SiegeEvent) ?? mobileParty.TargetSettlement ?? mobileParty.CurrentSettlement ?? mobileParty.LastVisitedSettlement;
}

private static string GetLocationLabelForPartyBase(PartyBase party)
{
	string text = GetNearestSettlementNameForParty(party?.MobileParty);
	return string.IsNullOrWhiteSpace(text) ? "" : text;
}

private static string ResolveGatheringPointLabel(IMapPoint gatheringPoint, MobileParty fallbackParty = null)
{
	Settlement settlement = ResolveGatheringPointSettlement(gatheringPoint, fallbackParty);
	string text = (settlement?.Name?.ToString() ?? "").Trim();
	if (!string.IsNullOrWhiteSpace(text))
	{
		return text;
	}
	text = (gatheringPoint?.Name?.ToString() ?? "").Trim();
	if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, "集结地", StringComparison.OrdinalIgnoreCase) && !string.Equals(text, "Gathering Point", StringComparison.OrdinalIgnoreCase))
	{
		return text;
	}
	text = GetNearestSettlementNameForParty(fallbackParty);
	return string.IsNullOrWhiteSpace(text) ? "集结地" : text;
}

private static NpcActionFacts CreateNpcActionFacts(string actionKind, Hero actorHero = null)
{
	NpcActionFacts npcActionFacts = new NpcActionFacts
	{
		ActionKind = (actionKind ?? "").Trim()
	};
	ApplyActorFacts(npcActionFacts, actorHero);
	return npcActionFacts;
}

private static void ApplyActorFacts(NpcActionFacts facts, Hero hero)
{
	if (facts == null || hero == null)
	{
		return;
	}
	facts.ActorHeroId = GetHeroId(hero);
	facts.ActorClanId = GetClanId(hero.Clan);
	facts.ActorKingdomId = GetKingdomId(hero.MapFaction);
	AddUniqueId(facts.RelatedHeroIds, facts.ActorHeroId);
	AddUniqueId(facts.RelatedClanIds, facts.ActorClanId);
	AddUniqueId(facts.RelatedKingdomIds, facts.ActorKingdomId);
}

private static void ApplyTargetFacts(NpcActionFacts facts, Hero hero)
{
	if (facts == null || hero == null)
	{
		return;
	}
	facts.TargetHeroId = GetHeroId(hero);
	facts.TargetClanId = GetClanId(hero.Clan);
	facts.TargetKingdomId = GetKingdomId(hero.MapFaction);
	AddUniqueId(facts.RelatedHeroIds, facts.TargetHeroId);
	AddUniqueId(facts.RelatedClanIds, facts.TargetClanId);
	AddUniqueId(facts.RelatedKingdomIds, facts.TargetKingdomId);
}

private static void ApplySettlementFacts(NpcActionFacts facts, Settlement settlement, Hero currentOwnerOverride = null, Hero previousOwnerOverride = null, string locationText = null)
{
	if (facts == null || settlement == null)
	{
		return;
	}
	facts.SettlementId = GetSettlementId(settlement);
	facts.SettlementName = (settlement.Name?.ToString() ?? "").Trim();
	facts.LocationText = string.IsNullOrWhiteSpace(locationText) ? facts.SettlementName : locationText.Trim();
	Hero hero = currentOwnerOverride ?? settlement.OwnerClan?.Leader;
	Hero hero2 = previousOwnerOverride;
	facts.SettlementOwnerHeroId = GetHeroId(hero);
	facts.SettlementOwnerClanId = GetClanId(hero?.Clan ?? settlement.OwnerClan);
	facts.SettlementOwnerKingdomId = GetKingdomId(hero?.MapFaction ?? settlement.MapFaction);
	facts.PreviousSettlementOwnerHeroId = GetHeroId(hero2);
	facts.PreviousSettlementOwnerClanId = GetClanId(hero2?.Clan);
	facts.PreviousSettlementOwnerKingdomId = GetKingdomId(hero2?.MapFaction);
	AddUniqueId(facts.RelatedHeroIds, facts.SettlementOwnerHeroId);
	AddUniqueId(facts.RelatedClanIds, facts.SettlementOwnerClanId);
	AddUniqueId(facts.RelatedKingdomIds, facts.SettlementOwnerKingdomId);
	AddUniqueId(facts.RelatedHeroIds, facts.PreviousSettlementOwnerHeroId);
	AddUniqueId(facts.RelatedClanIds, facts.PreviousSettlementOwnerClanId);
	AddUniqueId(facts.RelatedKingdomIds, facts.PreviousSettlementOwnerKingdomId);
}

private static void AddRelatedFactionFacts(NpcActionFacts facts, IFaction faction)
{
	if (facts == null || faction == null)
	{
		return;
	}
	if (faction is Kingdom kingdom)
	{
		string kingdomId = GetKingdomId(kingdom);
		if (string.IsNullOrWhiteSpace(facts.TargetKingdomId))
		{
			facts.TargetKingdomId = kingdomId;
		}
		AddUniqueId(facts.RelatedKingdomIds, kingdomId);
		return;
	}
	if (faction is Clan clan)
	{
		string clanId = GetClanId(clan);
		if (string.IsNullOrWhiteSpace(facts.TargetClanId))
		{
			facts.TargetClanId = clanId;
		}
		if (string.IsNullOrWhiteSpace(facts.TargetKingdomId))
		{
			facts.TargetKingdomId = GetKingdomId(clan.Kingdom);
		}
		AddUniqueId(facts.RelatedClanIds, clanId);
		AddUniqueId(facts.RelatedKingdomIds, GetKingdomId(clan.Kingdom));
	}
}

private static void AddUniqueId(List<string> list, string id)
{
	string text = (id ?? "").Trim();
	if (list == null || string.IsNullOrWhiteSpace(text))
	{
		return;
	}
	if (!list.Any((string x) => string.Equals((x ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase)))
	{
		list.Add(text);
	}
}

private static void CopyFactIds(List<string> source, List<string> destination)
{
	if (source == null || destination == null)
	{
		return;
	}
	foreach (string item in source)
	{
		AddUniqueId(destination, item);
	}
}

public static List<string> GetRecentKingdomEventFactsForExternal(string kingdomId, int limit)
	{
		List<string> facts = new List<string>();
		try
		{
			MyBehavior behavior = Instance ?? Campaign.Current?.GetCampaignBehavior<MyBehavior>();
			string id = (kingdomId ?? "").Trim();
			if (behavior?._eventSourceMaterials == null || string.IsNullOrWhiteSpace(id)) return facts;
			foreach (EventSourceMaterialEntry entry in behavior._eventSourceMaterials.Where(x => x != null && string.Equals((x.KingdomId ?? "").Trim(), id, StringComparison.OrdinalIgnoreCase)).Reverse().Take(Math.Max(1, limit)))
			{
				string kind = (entry.MaterialKind ?? "").Trim();
				if (kind != "war_declared" && kind != "peace_made" && kind != "raid_completed" && kind != "kingdom_decision_support" && kind != "clan_destroyed" && kind != "player_execution" && kind != "siege_aftermath") continue;
				facts.Add(kind + "\t" + (entry.StableKey ?? "") + "\t" + LimitEventFact((entry.Label ?? "") + " " + (entry.SnapshotText ?? "")));
			}
		}
		catch (Exception ex)
		{
			Logger.Log("KingdomCivilWar", "[WARN] recent event facts failed: " + ex.Message);
		}
		return facts;
	}

	private static string LimitEventFact(string text)
	{
		string value = (text ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
		return value.Length <= 80 ? value : value.Substring(0, 80);
	}

