		if (hero != null)
		{
			stringBuilder.AppendLine($"年龄: {hero.Age:F0}");
		}
	}
	catch
	{
	}
	try
	{
		if (hero != null)
		{
			stringBuilder.AppendLine("性别: " + (hero.IsFemale ? "女" : "男"));
