	string[] array = text.Split(new char[1] { '\n' }, StringSplitOptions.RemoveEmptyEntries);
	List<string> list = new List<string>();
	for (int i = 0; i < array.Length; i++)
	{
		string text2 = (array[i] ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text2))
		{
			list.Add(text2);
