private string BuildMatchedExtraRuleInstructionsFromPreselectedRules(IEnumerable<string> preselectedRuleIds, int maxRules, bool hasAnyHero, HashSet<string> excludedRuleIdSet, Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex)
{
	try
	{
		List<string> ruleIds = PromptRuleIdPolicy.NormalizePreselectedRuleIds(preselectedRuleIds);
		if (ruleIds.Count == 0)
		{
			return "";
		}
		int limit = Math.Max(1, maxRules <= 0 ? AIConfigHandler.GuardrailRuleReturnCap : maxRules);
		StringBuilder sb = new StringBuilder();
		int added = 0;
		foreach (string ruleId in ruleIds)
		{
			if (added >= limit)
			{
				break;
			}
			if (PromptRuleIdPolicy.IsBuiltInRuleIdForExtraInjection(ruleId) || PromptRuleIdPolicy.IsExcluded(excludedRuleIdSet, ruleId))
			{
				continue;
			}
			if (PromptRuleIdPolicy.IsRuntimeGatedPreprocessRuleId(ruleId)
				&& !AIConfigHandler.CanInjectRuleTopicIntoPreprocessForExternal(ruleId, hasAnyHero))
			{
				continue;
			}
			string body = hasAnyHero ? AIConfigHandler.GetGuardrailRuleInstruction(ruleId) : AIConfigHandler.GetGuardrailRuleNonHeroInstruction(ruleId);
			if (string.IsNullOrWhiteSpace(body))
			{
				body = AIConfigHandler.GetGuardrailRuleInstruction(ruleId);
			}
			body = ResolvePreselectedRuleInstructionBody(ruleId, body, hasAnyHero, targetHero, targetCharacter, targetAgentIndex);
			if (string.IsNullOrWhiteSpace(body))
			{
				continue;
			}
			PromptRuleBlockText.Append(sb, ruleId, body);
			added++;
		}
		return sb.ToString().Trim();
	}
	catch
	{
		return "";
	}
}

