		}
		else
		{
			stringBuilder.Append("接口请求失败");
		}
		stringBuilder.Append("（HTTP ").Append(text).Append("）");
		if (retryAfterSeconds.HasValue)
		{
			stringBuilder.Append("，建议等待 ").Append(retryAfterSeconds.Value).Append(" 秒后再试");
