private static string BuildWeeklyEpicWeekLabel(int weekIndex)
{
	if (weekIndex <= 0)
	{
		return "第0周";
	}
	const int num = 7;
	const int num2 = 21;
	const int num3 = 84;
	int num4 = Math.Max(0, (weekIndex - 1) * num);
	int num5 = num4 / num3;
	int num6 = num4 % num3;
	int seasonIndexZeroBased = num6 / num2;
	int num7 = Math.Min(3, num6 % num2 / num + 1);
	string seasonTextZhForPrompt = GetSeasonTextZhForPrompt(seasonIndexZeroBased);
	return num5 + "年" + seasonTextZhForPrompt + "季" + ConvertWeekNumberToChineseOrdinal(num7) + "周";
}

private static string ConvertWeekNumberToChineseOrdinal(int weekNumber)
{
	switch (weekNumber)
	{
	case 1:
		return "第一";
	case 2:
		return "第二";
	case 3:
		return "第三";
	case 4:
		return "第四";
	case 5:
		return "第五";
	case 6:
		return "第六";
	case 7:
		return "第七";
	case 8:
		return "第八";
	case 9:
		return "第九";
	case 10:
		return "第十";
	default:
		return "第" + Math.Max(1, weekNumber);
	}
}

