private static string BuildWeeklyReportPopupBodyText(EventRecordEntry entry)
{
	if (entry == null)
	{
		return "当前周报正文为空。";
	}
	string text = (entry.Summary ?? "").Trim();
	if (!string.IsNullOrWhiteSpace(text))
	{
		return text;
