public static bool TrySubmitNativeConversationTagTestForExternal(string rawText, out string statusText)
{
	statusText = "";
	try
	{
		if (!CanOpenNativeConversationTagTestForExternal())
		{
			statusText = "数据管理未开启，或当前没有可测试的对话目标。";
			return false;
		}
