	}
	catch (Exception ex)
	{
		LogNonHeroMemoryTrace("stage=uncompressed_inject agent=" + targetAgentIndex + " memoryId= reason=exception messages=0 error=" + ex.Message);
		return new List<ConversationMessage>();
	}
}

