		if (dictionary == null || !dictionary.TryGetValue(npcActionHeroKey, out var value) || value == null)
		{
			return new List<NpcActionEntry>();
		}
		return NpcActionLedger.SanitizeNpcActionEntries(value, recentOnly, currentDay());
	}
}

