		if (context.Batches == null || context.Batches.Count == 0)
		{
			context.Batches = BuildWeeklyReportBatchRequests((context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).ToList(), context.WeekIndex, context.StartDay, context.EndDay, _port.IsKingdomEligible, _port.BatchSize());
		}
