			&& context.BatchPromptCursor.TryTake(out WeeklyReportBatchRequest batch))
		{
			PrepareWeeklyReportBatchPrompt(batch);
		}
	}

internal void PrepareWeeklyReportBatchPrompt(WeeklyReportBatchRequest batch)
	{
		if (batch == null)
		{
			return;
		}
		if (!WeeklyGenerationRules.IsWeeklyReportBatchPromptPrepared(batch))
		{
			batch.SystemPrompt = _port.BatchSystem(batch) ?? "";
			batch.UserPrompt = _port.BatchUser(batch) ?? "";
		}
		if (string.IsNullOrWhiteSpace(batch.PromptPreview))
		{
			batch.PromptPreview = _port.BatchPreview(batch, batch.SystemPrompt, batch.UserPrompt);
		}
		if (string.IsNullOrWhiteSpace(batch.DisplayLabel))
		{
			batch.DisplayLabel = BuildWeeklyReportBatchDisplayLabel(batch);
		}
	}

internal bool ProcessPendingAutoWeeklyReportPreviewGroupsBudget(PendingAutoWeeklyReportBuild context, long startTimestamp, double budgetMs)
	{
		if (context == null)
		{
			return true;
		}
		if (!context.PreviewGroupsInitialized)
		{
			context.Groups = new List<WeeklyEventMaterialPreviewGroup>
			{
				_port.WeeklyRecords.CreateWorldWeeklyEventMaterialPreviewGroup()
			};
			foreach (Kingdom kingdom in context.Kingdoms ?? new List<Kingdom>())
			{
				context.Groups.Add(MemoryEntityIdentityBannerlordAdapter.CreateKingdomWeeklyEventMaterialPreviewGroup(_port.WeeklyRecords, kingdom));
			}
			context.RecentActionCursor = new WeeklyActionMaterialCursor<NpcActionEntry, Hero>((_port.MemoryState.RecentActions ?? new Dictionary<string, List<NpcActionEntry>>()).ToList());
			context.MajorActionCursor = new WeeklyActionMaterialCursor<NpcActionEntry, Hero>((_port.MemoryState.MajorActions ?? new Dictionary<string, List<NpcActionEntry>>()).ToList());
			context.PreviewGroupsInitialized = true;
			return false;
		}
		while (context.PreviewSourceMaterialIndex < (context.EventSourceMaterialSnapshot?.Count ?? 0) && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			EventSourceMaterialEntry item = context.EventSourceMaterialSnapshot[context.PreviewSourceMaterialIndex++];
			ProcessPendingAutoWeeklyReportSourceMaterial(context, item);
		}
		if (context.PreviewSourceMaterialIndex < (context.EventSourceMaterialSnapshot?.Count ?? 0))
		{
			return false;
		}
		while (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) && !ProcessPendingAutoWeeklyReportActionSlice(context, recentOnly: true))
		{
		}
		if (context.RecentActionCursor != null && !context.RecentActionCursor.Complete)
		{
			return false;
		}
		while (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) && !ProcessPendingAutoWeeklyReportActionSlice(context, recentOnly: false))
		{
		}
		return context.MajorActionCursor == null || context.MajorActionCursor.Complete;
	}

internal void ProcessPendingAutoWeeklyReportSourceMaterial(PendingAutoWeeklyReportBuild context, EventSourceMaterialEntry item)
	{
		if (context == null || item == null || item.Day < context.StartDay || item.Day > context.EndDay || context.Groups == null || context.Groups.Count == 0)
		{
			return;
		}
		if (item.IncludeInWorld)
		{
			CampaignCharacterRecordCaptureAdapter.TryAddPreviewSourceMaterial(context.Groups[0].Materials, item);
		}
		for (int i = 0; i < context.Kingdoms.Count && i + 1 < context.Groups.Count; i++)
		{
			Kingdom kingdom = context.Kingdoms[i];
			if (item.IncludeInKingdom && MemoryEntityIdentityBannerlordAdapter.IsKingdomEligibleForWeeklyReport(kingdom) && CampaignMaterialRecordOwner.DoesEventSourceMaterialRelateToKingdom(item, kingdom?.StringId))
			{
				CampaignCharacterRecordCaptureAdapter.TryAddPreviewSourceMaterial(context.Groups[i + 1].Materials, item);
			}
		}
	}

internal bool ProcessPendingAutoWeeklyReportActionSlice(PendingAutoWeeklyReportBuild context, bool recentOnly)
	{
		if (context == null)
		{
			return true;
		}
		WeeklyActionMaterialCursor<NpcActionEntry, Hero> cursor = recentOnly ? context.RecentActionCursor : context.MajorActionCursor;
		return cursor == null || cursor.Advance(MemoryEntityIdentityBannerlordAdapter.FindHeroById,
			(hero, action) => ProcessPendingAutoWeeklyReportNpcAction(context, hero, action, recentOnly));
	}

internal void ProcessPendingAutoWeeklyReportNpcAction(PendingAutoWeeklyReportBuild context, Hero hero, NpcActionEntry action, bool recentOnly)
	{
		if (context == null || hero == null || action == null || action.Day < context.StartDay || action.Day > context.EndDay || context.Groups == null || context.Groups.Count == 0)
		{
			return;
		}
		if (MemoryEntityIdentityBannerlordAdapter.ShouldIncludeWorldPreviewAction(hero, action))
		{
			_port.RecordCapture().TryAddPreviewActionMaterial(context.Groups[0].Materials, hero, action, recentOnly);
		}
		for (int i = 0; i < context.Kingdoms.Count && i + 1 < context.Groups.Count; i++)
		{
			Kingdom kingdom = context.Kingdoms[i];
			if (!MemoryEntityIdentityBannerlordAdapter.IsKingdomEligibleForWeeklyReport(kingdom) || !NpcActionRecordOwner.DoesNpcActionRelateToKingdom(action, kingdom?.StringId))
			{
				continue;
			}
			if (!recentOnly || MemoryEntityIdentityBannerlordAdapter.ShouldIncludeKingdomPreviewAction(hero, action, kingdom))
			{
				_port.RecordCapture().TryAddPreviewActionMaterial(context.Groups[i + 1].Materials, hero, action, recentOnly);
			}
		}
	}

internal void TryInitializePendingAutoWeeklyReportBuild(DailyMaintenanceJob job)
	{
		if (job == null || job.WeekIndex <= 0 || _lastAutoGeneratedWeeklyReportWeek >= job.WeekIndex)
		{
			return;
		}
		if (_weeklyReportGenerationInProgress || _pendingAutoWeeklyReportBuild != null)
		{
			if (_pendingAutoWeeklyReportBuild == null || _pendingAutoWeeklyReportBuild.WeekIndex != job.WeekIndex)
			{
				_port.AutoSchedule.Defer(job.WeekIndex);
			}
			return;
		}
		if (_port.RebellionFlow())
		{
			_port.AutoSchedule.Defer(job.WeekIndex);
			return;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		if (settings == null || !settings.IsLegacyWeeklyAutoGenerationActive())
		{
			return;
		}
		_pendingAutoWeeklyReportBuild = new PendingAutoWeeklyReportBuild
		{
			SourceSnapshot = _weeklyReportMaterialRevisions.Capture(Math.Max(0, job.StartDay), Math.Max(job.StartDay, job.EndDay)),
			WeekIndex = job.WeekIndex,
			StartDay = Math.Max(0, job.StartDay),
			EndDay = Math.Max(job.StartDay, job.EndDay),
			Kingdoms = EventEditorProjection.GetDevEditableKingdoms().Where(MemoryEntityIdentityBannerlordAdapter.IsKingdomEligibleForWeeklyReport).ToList(),
			EventSourceMaterialSnapshot = CampaignMaterialRecordOwner.SanitizeEventSourceMaterials(_port.MaterialState.Materials)
		};
		_weeklyReportGenerationInProgress = true;
		_port.AutoSchedule.Clear();
	}

internal void ProcessPendingAutoWeeklyReportBuildBudget(long startTimestamp, double budgetMs)
	{
		PendingAutoWeeklyReportBuild context = _pendingAutoWeeklyReportBuild;
		if (context == null || _port.RebellionFlow())
		{
			return;
		}
		try
		{
			if (!context.PreviewGroupsComplete && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				using (PerfProbe.Scope("MyBehavior.AutoWeeklyReport.BuildPreviewGroupsSlice"))
				{
					context.PreviewGroupsComplete = ProcessPendingAutoWeeklyReportPreviewGroupsBudget(context, startTimestamp, budgetMs);
				}
			}
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.PreviewGroupsComplete)
			{
				return;
			}
			ProcessPendingWeeklyReportAggregationBudget(context, startTimestamp, budgetMs);
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || context.AggregationCursor?.Complete != true)
			{
				return;
			}
			ProcessPendingWeeklyReportPromptMaterialsBudget(context, startTimestamp, budgetMs);
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || context.PromptMaterialCursor?.Complete != true)
			{
				return;
			}
			if (!context.Ordered && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				context.Groups = MemoryEntityIdentityBannerlordAdapter.OrderWeeklyReportGenerationGroups((context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).ToList());
				context.Ordered = true;
			}
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || !context.Ordered)
			{
				return;
			}
			ProcessPendingWeeklyReportBatchPromptsBudget(context, startTimestamp, budgetMs);
			if (IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs) || context.BatchPromptCursor?.Complete != true)
			{
				return;
			}
			if (!IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
			{
				FinalizePendingAutoWeeklyReportBuild(context);
			}
		}
		catch (Exception ex)
		{
			_pendingAutoWeeklyReportBuild = null;
			_weeklyReportGenerationInProgress = false;
			Logger.Log("EventWeeklyReport", "[ERROR] deferred auto weekly report build failed: " + ex);
		}
	}

internal void FinalizePendingAutoWeeklyReportBuild(PendingAutoWeeklyReportBuild context)
	{
		if (context == null)
		{
			return;
		}
		List<WeeklyEventMaterialPreviewGroup> groups = (context.Groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Where((WeeklyEventMaterialPreviewGroup x) => x != null).ToList();
		List<WeeklyReportBatchRequest> batches = (context.Batches ?? new List<WeeklyReportBatchRequest>()).Where((WeeklyReportBatchRequest x) => x != null && x.Groups != null && x.Groups.Count > 0).ToList();
		_pendingAutoWeeklyReportBuild = null;
		_ = GenerateAutoWeeklyReportsAsync(groups, context.WeekIndex, context.StartDay, context.EndDay, batches, context.SourceSnapshot);
	}

internal void StartAutoWeeklyReportsForWeek(int weekIndex, int currentGameDayIndexSafe)
	{
		if (weekIndex <= 0 || _lastAutoGeneratedWeeklyReportWeek >= weekIndex || _weeklyReportGenerationInProgress || _port.WorldBulletinEnabled())
		{
			return;
		}
		if (_port.RebellionFlow())
		{
			_port.AutoSchedule.Defer(weekIndex);
			return;
		}
		int startDay = WeeklyReportSchedulePolicy.GetStartDay(weekIndex);
		int endDay = WeeklyReportSchedulePolicy.GetEndDay(weekIndex);
		WeeklyReportMaterialRevisionOwner.Snapshot sourceSnapshot = _weeklyReportMaterialRevisions.Capture(startDay, endDay);
		List<WeeklyEventMaterialPreviewGroup> list = MemoryEntityIdentityBannerlordAdapter.OrderWeeklyReportGenerationGroups(_port.RecordCapture().BuildWeeklyEventMaterialPreviewGroups(startDay, endDay));
		_weeklyReportGenerationInProgress = true;
		_port.AutoSchedule.Clear();
		_ = GenerateAutoWeeklyReportsAsync(list, weekIndex, startDay, endDay, sourceSnapshotOverride: sourceSnapshot);
	}

internal void TryStartDeferredAutoWeeklyReports()
	{
		if (_port.AutoSchedule.PendingWeek <= 0 || _weeklyReportGenerationInProgress || _port.RebellionFlow())
		{
			return;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		if (settings == null || !settings.IsLegacyWeeklyAutoGenerationActive())
		{
			return;
		}
		int currentGameDayIndexSafe = _port.CurrentDay();
		int missingWeek = _port.AutoSchedule.ResolvePendingWeek(_lastAutoGeneratedWeeklyReportWeek,
			currentGameDayIndexSafe, _weeklyReportGenerationInProgress,
			settings != null && settings.IsLegacyWeeklyAutoGenerationActive(), _port.RebellionFlow());
		if (missingWeek <= 0)
		{
			return;
		}
		if (CampaignDailyMaintenanceController.IsDeferredDailyMaintenanceEnabled())
		{
			_port.QueueDeferredWeekly(_port.AutoSchedule.PendingWeek, currentGameDayIndexSafe, "deferred_auto_weekly_resume");
		}
		else
		{
			StartAutoWeeklyReportsForWeek(missingWeek, currentGameDayIndexSafe);
		}
	}

internal async Task GenerateAutoWeeklyReportsAsync(List<WeeklyEventMaterialPreviewGroup> groups, int weekIndex, int startDay, int endDay, List<WeeklyReportBatchRequest> preparedBatches = null, WeeklyReportMaterialRevisionOwner.Snapshot sourceSnapshotOverride = null)
	{
		long runtimeGeneration = _port.CaptureGeneration();
		try
		{
			WeeklyReportGenerationResult weeklyReportGenerationResult = await GenerateWeeklyReportsMinuteBurstAsyncInternal(groups, weekIndex, startDay, endDay, _port.EpicWeekLabel(weekIndex) + "自动周报", openViewerWhenDone: false, queueBlockingPopupOnFatalFailure: true, isAutoGeneration: true, popupCandidateKingdomIdsOverride: null, preparedBatches: preparedBatches, runtimeGeneration: runtimeGeneration, sourceSnapshotOverride: sourceSnapshotOverride);
			if (!_port.IsStale(runtimeGeneration, "auto_weekly_report_complete") && weeklyReportGenerationResult != null && weeklyReportGenerationResult.Completed && !weeklyReportGenerationResult.BlockedByFatalFailure)
			{
				_lastAutoGeneratedWeeklyReportWeek = Math.Max(_lastAutoGeneratedWeeklyReportWeek, weekIndex);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("EventWeeklyReport", "[ERROR] GenerateAutoWeeklyReportsAsync failed: " + ex);
		}
		finally
		{
			if (_port.IsCurrentGeneration(runtimeGeneration))
			{
				_weeklyReportGenerationInProgress = false;
			}
		}
	}

internal static int GetWeeklyReportRequestIntervalMs(int weeklyReportRequestsPerMinute)
	{
		double num = 60000.0 / Math.Max(1, weeklyReportRequestsPerMinute);
		return Math.Max(0, (int)Math.Ceiling(num));
	}

