internal static List<WeeklyEventMaterialPreviewGroup> BuildRemainingWeeklyReportGroupsForRetry(List<WeeklyReportBatchRequest> batches, int batchIndex, IEnumerable<WeeklyEventMaterialPreviewGroup> currentBatchRemainingGroups)
	{
		List<WeeklyEventMaterialPreviewGroup> list = new List<WeeklyEventMaterialPreviewGroup>();
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		void AddGroup(WeeklyEventMaterialPreviewGroup group)
		{
			string text = BuildWeeklyReportGroupReportId(group);
			if (group != null && !string.IsNullOrWhiteSpace(text) && hashSet.Add(text))
			{
				list.Add(group);
			}
		}
		foreach (WeeklyEventMaterialPreviewGroup item in currentBatchRemainingGroups ?? Enumerable.Empty<WeeklyEventMaterialPreviewGroup>())
		{
			AddGroup(item);
		}
		for (int i = batchIndex + 1; i < (batches?.Count ?? 0); i++)
		{
			foreach (WeeklyEventMaterialPreviewGroup item2 in batches[i]?.Groups ?? new List<WeeklyEventMaterialPreviewGroup>())
			{
				AddGroup(item2);
			}
		}
		return list;
	}

internal async Task<ApiCallResult> CallWeeklyReportBatchApiAttemptAsync(string systemPrompt, string userPrompt, long runtimeGeneration, bool firstAttempt)
	{
		if (!_port.IsCurrentOwner() || (runtimeGeneration > 0L && _port.IsStale(runtimeGeneration, "weekly_batch_before_api_attempt")))
		{
			return new ApiCallResult { ErrorMessage = SaveRuntimeGuard.BuildStaleRequestErrorText() };
		}
		if (firstAttempt && _port.IsMainThread())
		{
			return await _port.CallApi(systemPrompt, userPrompt).ConfigureAwait(false);
		}
		TaskCompletionSource<Task<ApiCallResult>> completionSource = new TaskCompletionSource<Task<ApiCallResult>>(TaskCreationOptions.RunContinuationsAsynchronously);
		_weeklyBatchApiAttemptQueue.EnqueueIfCurrent(new PendingWeeklyBatchApiAttemptContext
		{
			RuntimeGeneration = runtimeGeneration,
			SystemPrompt = systemPrompt,
			UserPrompt = userPrompt,
			CompletionSource = completionSource
		}, () => _port.IsCurrentOwner() && _port.IsCurrentGeneration(runtimeGeneration));
		Task<ApiCallResult> attempt = await completionSource.Task.ConfigureAwait(false);
		if (attempt == null || !_port.IsCurrentOwner() || (runtimeGeneration > 0L && _port.IsStale(runtimeGeneration, "weekly_batch_after_api_launch")))
		{
			return new ApiCallResult { ErrorMessage = SaveRuntimeGuard.BuildStaleRequestErrorText() };
		}
		return await attempt.ConfigureAwait(false);
	}

internal async Task<WeeklyReportBatchExecutionResult> ExecuteWeeklyReportBatchAsync(WeeklyReportBatchRequest batch, int batchIndex, int maxAttempts, long runtimeGeneration)
	{
		Stopwatch stopwatch = Stopwatch.StartNew();
		WeeklyReportBatchRequestResult result;
		try
		{
			result = await _port.GenerationAttempt.GenerateWeeklyReportBatchWithRetriesAsync(batch, maxAttempts, runtimeGeneration, BuildWeeklyReportBatchDisplayLabel(batch), _port.AttemptPort());
		}
		catch (Exception ex)
		{
			result = new WeeklyReportBatchRequestResult
			{
				Success = false,
				FailureReason = "Batch execution crashed: " + ex.Message,
				AttemptsUsed = 1,
				Blocks = new List<WeeklyReportBatchBlockResult>(),
				MissingReportIds = (batch?.Groups ?? new List<WeeklyEventMaterialPreviewGroup>()).Select(BuildWeeklyReportGroupReportId).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList()
			};
		}
		stopwatch.Stop();
		return new WeeklyReportBatchExecutionResult
		{
			BatchIndex = batchIndex,
			Batch = batch,
			Result = result,
			ElapsedMilliseconds = (long)Math.Max(0.0, stopwatch.Elapsed.TotalMilliseconds)
		};
	}

