internal async Task<bool> GenerateWeeklyReportFullByEventIdAsync(string eventId)
	{
		// Capture live records and prompts only at the UI/main-thread boundary.
		if (!_port.IsMainThread() || !_port.IsCurrentOwner())
		{
			Logger.Log("EventWeeklyReport", "[FullOnDemand] rejected non-current main-thread owner");
			return false;
		}
		long runtimeGeneration = _port.CaptureGeneration();
		EventRecordEntry eventRecordEntry = FindWeeklyReportRecordById(eventId);
		if (eventRecordEntry == null)
		{
			_port.FullFailure("未找到该期周报记录。");
			return false;
		}
		if (!string.IsNullOrWhiteSpace(eventRecordEntry.Summary))
		{
			return true;
		}
		WeeklyEventMaterialPreviewGroup weeklyEventMaterialPreviewGroup = BuildWeeklyReportRecordPreviewGroup(eventRecordEntry);
		if (weeklyEventMaterialPreviewGroup == null || (weeklyEventMaterialPreviewGroup.Materials?.Count ?? 0) == 0)
		{
			_port.FullFailure("该期周报没有可用的完整素材。");
			return false;
		}
		int num = Math.Max(1, eventRecordEntry.WeekIndex);
		string text = _port.FullSystem(weeklyEventMaterialPreviewGroup);
		string text2 = _port.FullUser(weeklyEventMaterialPreviewGroup, num);
		string text3 = _port.FullPreview(weeklyEventMaterialPreviewGroup, text, text2);
		string capturedEventId = eventRecordEntry.EventId;
		string capturedSource = BuildWeeklyFullReportSourceState(eventRecordEntry);
		_port.FullProgress(eventRecordEntry);
		try
		{
			ApiCallResult apiCallResult = await _port.CallApi(text, text2).ConfigureAwait(false);
			return await _port.FullCompletions.Enqueue(runtimeGeneration, () =>
			{
				EventRecordEntry currentEntry = FindWeeklyReportRecordById(capturedEventId);
				if (currentEntry != null && !string.IsNullOrWhiteSpace(currentEntry.Summary))
				{
					// Another accepted request won the race; never overwrite its report.
					_port.HideInquiry();
					return true;
				}
				if (currentEntry == null || !string.Equals(capturedSource, BuildWeeklyFullReportSourceState(currentEntry), StringComparison.Ordinal))
				{
					_port.FullFailure("该期周报或素材已变更，请重新选择后生成。");
					return false;
				}
				if (apiCallResult == null || !apiCallResult.Success)
				{
					_port.FullFailure("完整周报生成失败：" + (apiCallResult?.ErrorMessage ?? "未知错误"));
					return false;
				}
				if (!_port.ParseFullResponse(apiCallResult.Content, out var title, out var shortSummary, out var report))
				{
					_port.FullFailure(LlmRetryPrompt.BuildFailureDetail("完整周报返回内容无法解析。", apiCallResult.Content, apiCallResult.ResponseBody));
					return false;
				}
				string previousPublishedProductState = _port.ProductState(currentEntry);
				currentEntry.Title = title;
				currentEntry.ShortSummary = WeeklyGenerationRules.BuildFallbackWeeklyReportShortSummary(shortSummary);
				currentEntry.Summary = (report ?? "").Trim();
				currentEntry.PromptText = text3;
				currentEntry.Materials = CloneWeeklyReportMaterials(currentEntry.Materials);
				_eventRecordEntries = _port.SanitizeRecords(_eventRecordEntries);
				_port.NotifyProduct(previousPublishedProductState, FindWeeklyReportRecordById(capturedEventId));
				_port.NotifyTimeline();
				_port.HideInquiry();
				_port.DisplayMessage("完整周报已生成。");
				return true;
			}).ConfigureAwait(false);
		}
		catch (Exception ex)
		{
			return await _port.FullCompletions.Enqueue(runtimeGeneration, () =>
			{
				_port.FullFailure("完整周报生成失败：" + ex.Message);
				return false;
			}).ConfigureAwait(false);
		}
	}


internal static string TranslateEventKindForDev(string eventKind)
	{
		switch ((eventKind ?? "").Trim().ToLowerInvariant())
		{
		case "world":
			return "世界事件";
		case "kingdom":
			return "王国事件";
		case "player_local":
			return "玩家周边事件";
		default:
			return string.IsNullOrWhiteSpace(eventKind) ? "未分类事件" : eventKind.Trim();
		}
	}

internal static string TranslateEventMaterialTypeForDev(string materialType)
	{
		string text = (materialType ?? "").Trim().ToLowerInvariant();
		if (text.StartsWith("prompt_agg_", StringComparison.OrdinalIgnoreCase))
		{
			return "周报聚合素材";
		}
