	int num4 = (int)((colorB >> 16) & 0xFF);
	int num5 = (int)((colorB >> 8) & 0xFF);
	int num6 = (int)(colorB & 0xFF);
	return Math.Abs(num - num4) + Math.Abs(num2 - num5) + Math.Abs(num3 - num6);
}

