		text2 = Regex.Replace(text2, "\\（.*?\\）", "", RegexOptions.Singleline);
		text2 = Regex.Replace(text2, "\\(.*?\\)", "", RegexOptions.Singleline);
		text2 = Regex.Replace(text2, "\\*\\*.*?\\*\\*", "", RegexOptions.Singleline);
		text2 = Regex.Replace(text2, "\\*.*?\\*", "", RegexOptions.Singleline);
		text2 = Regex.Replace(text2, "(^|\\n)\\s*【[^】\\r\\n]{1,40}】", "$1");
		text2 = StripTtsNarrationLines(text2);
